import { createFocusTrap as originalCreateFocusTrap } from 'focus-trap';
import { addNeonToolkit, getNeonToolkit, neonToolkitHas } from '../../../exported-utils/neon-toolkit';
import { getRootDoc } from './dom-manipulation';
export function createFocusTrap(element, userOptions) {
    if (!neonToolkitHas('neon-all-versions-focus-traps')) {
        addNeonToolkit('neon-all-versions-focus-traps', []);
    }
    const defaultOptions = {
        //The focus trap Options interface says that
        //the document needs to be of type Document.
        //However, it turns out that if we cast a DocumentFragment to type Document
        //that things still seem to work.
        //Note: it is a bit risky to cast like this, but so far things seem to work.
        document: getRootDoc(element)
    };
    const options = Object.assign(defaultOptions, userOptions);
    options.trapStack = getNeonToolkit('neon-all-versions-focus-traps');
    options.tabbableOptions = {
        getShadowRoot: true
    };
    return originalCreateFocusTrap(element, options);
}
